40	/**
41	 * The {@link OsProbe} class retrieves information about the physical and swap size of the machine
42	 * memory, as well as the system load average and cpu load.
43	 *
44	 * <p>In some exceptional cases, it's possible the underlying native methods used by
45	 * {@link #getFreePhysicalMemorySize()}, {@link #getTotalPhysicalMemorySize()},
46	 * {@link #getFreeSwapSpaceSize()}, and {@link #getTotalSwapSpaceSize()} can return a
47	 * negative value. Because of this, we prevent those methods from returning negative values,
48	 * returning 0 instead.
49	 *
50	 * <p>The OS can report a negative number in a number of cases:
51	 *
52	 * <ul>
53	 *   <li>Non-supported OSes (HP-UX, or AIX)
54	 *   <li>A failure of macOS to initialize host statistics
55	 *   <li>An OS that does not support the {@code _SC_PHYS_PAGES} or {@code _SC_PAGE_SIZE} flags for the {@code sysconf()} linux kernel call
56	 *   <li>An overflow of the product of {@code _SC_PHYS_PAGES} and {@code _SC_PAGE_SIZE}
57	 *   <li>An error case retrieving these values from a linux kernel
58	 *   <li>A non-standard libc implementation not implementing the required values
59	 * </ul>
60	 *
61	 * <p>For a more exhaustive explanation, see <a href="https://github.com/elastic/elasticsearch/pull/42725"
62	 *   >https://github.com/elastic/elasticsearch/pull/42725</a>
63	 */
64	public class OsProbe {
65	
66	    private static final OperatingSystemMXBean osMxBean = ManagementFactory.getOperatingSystemMXBean();
67	
68	    // This property is specified without units because it also needs to be parsed by the launcher
69	    // code, which does not have access to all the utility classes of the Elasticsearch server.
70	    private static final String memoryOverrideProperty = System.getProperty("es.total_memory_bytes");
71	
72	    private static final Method getFreePhysicalMemorySize;
73	    private static final Method getTotalPhysicalMemorySize;
74	    private static final Method getFreeSwapSpaceSize;
75	    private static final Method getTotalSwapSpaceSize;
76	    private static final Method getSystemLoadAverage;
77	    private static final Method getCpuLoad;
78	    private static final Method getAvailableProcessors;
79	
80	    static {
81	        getFreePhysicalMemorySize = getMethod("getFreePhysicalMemorySize");
82	        getTotalPhysicalMemorySize = getMethod("getTotalPhysicalMemorySize");
83	        getFreeSwapSpaceSize = getMethod("getFreeSwapSpaceSize");
84	        getTotalSwapSpaceSize = getMethod("getTotalSwapSpaceSize");
85	        getSystemLoadAverage = getMethod("getSystemLoadAverage");
86	        getCpuLoad = getMethod("getCpuLoad");
87	        getAvailableProcessors = getMethod("getAvailableProcessors");
88	    }
89	
90	    /**
91	     * Returns the amount of free physical memory in bytes.
92	     */
93	    public long getFreePhysicalMemorySize() {
94	        if (getFreePhysicalMemorySize == null) {
95	            logger.warn("getFreePhysicalMemorySize is not available");
96	            return 0;
97	        }
98	        try {
99	            final long freeMem = (long) getFreePhysicalMemorySize.invoke(osMxBean);
100	            if (freeMem < 0) {
101	                logger.debug("OS reported a negative free memory value [{}]", freeMem);
102	                return 0;
103	            }
104	            return freeMem;
105	        } catch (Exception e) {
106	            logger.warn("exception retrieving free physical memory", e);
107	            return 0;
108	        }
109	    }
110	
111	    /**
112	     * Returns the amount of actual free physical memory in bytes.
113	     * <p>
114	     * This method accounts for memory that can be reclaimed under pressure, reading {@code MemAvailable} from {@code /proc/meminfo}
115	     * when available, or otherwise falling back to {@code MemFree + Buffers + Cached}.
116	     * When {@code /proc/meminfo} can't be read or parsed, this falls back to {@link #getFreePhysicalMemorySize()}.
117	     */
118	    public long getActualFreePhysicalMemorySize() {
119	        if (Constants.LINUX == false) {
120	            return getFreePhysicalMemorySize();
121	        }
122	        try {
123	            List<String> meminfoLines = readProcMeminfo();
124	            long available = parseMeminfoKbToBytes(meminfoLines, "MemAvailable:");
125	            if (available >= 0) {
126	                return available;
127	            }
128	            long free = parseMeminfoKbToBytes(meminfoLines, "MemFree:");
129	            long buffers = parseMeminfoKbToBytes(meminfoLines, "Buffers:");
130	            long cached = parseMeminfoKbToBytes(meminfoLines, "Cached:");
131	            if (free >= 0 && buffers >= 0 && cached >= 0) {
132	                return free + buffers + cached;
133	            }
134	        } catch (Exception e) {
135	            logger.warn("exception retrieving actual free physical memory", e);
136	        }
137	        return getFreePhysicalMemorySize();
138	    }
139	
140	    private static long parseMeminfoKbToBytes(List<String> meminfoLines, String prefix) {
141	        for (String line : meminfoLines) {
142	            if (line.startsWith(prefix) == false) {
143	                continue;
144	            }
145	            int end = line.lastIndexOf(" kB");
146	            String number = line.substring(prefix.length(), end).trim();
147	            return Long.parseLong(number) * 1024;
148	        }
149	        return -1;
150	    }
151	
152	    /**
153	     * Returns the total amount of physical memory in bytes.
154	     */
155	    public long getTotalPhysicalMemorySize() {
156	        if (getTotalPhysicalMemorySize == null) {
157	            logger.warn("getTotalPhysicalMemorySize is not available");
158	            return 0;
159	        }
160	        try {
161	            long totalMem = (long) getTotalPhysicalMemorySize.invoke(osMxBean);
162	            if (totalMem < 0) {
163	                logger.debug("OS reported a negative total memory value [{}]", totalMem);
164	                return 0;
165	            }
166	            if (totalMem == 0 && isDebian8()) {
167	                // workaround for JDK bug on debian8: https://github.com/elastic/elasticsearch/issues/67089#issuecomment-756114654
168	                totalMem = getTotalMemFromProcMeminfo();
169	            }
170	
171	            return totalMem;
172	        } catch (Exception e) {
173	            logger.warn("exception retrieving total physical memory", e);
174	            return 0;
175	        }
176	    }
177	
178	    /**
179	     * Returns the adjusted total amount of physical memory in bytes.
180	     * Total memory may be overridden when some other process is running
181	     * that is known to consume a non-negligible amount of memory. This
182	     * is read from the "es.total_memory_bytes" system property. When
183	     * there is no override this method returns the same value as
184	     * {@link #getTotalPhysicalMemorySize}.
185	     */
186	    public long getAdjustedTotalMemorySize() {
187	        return Optional.ofNullable(getTotalMemoryOverride(memoryOverrideProperty)).orElse(getTotalPhysicalMemorySize());
188	    }
189	
190	    static Long getTotalMemoryOverride(String memoryOverrideProperty) {
191	        if (memoryOverrideProperty == null) {
192	            return null;
193	        }
194	        try {
195	            long memoryOverride = Long.parseLong(memoryOverrideProperty);
196	            if (memoryOverride < 0) {
197	                throw new IllegalArgumentException(
198	                    "Negative memory size specified in [es.total_memory_bytes]: [" + memoryOverrideProperty + "]"
199	                );
200	            }
201	            return memoryOverride;
202	        } catch (NumberFormatException e) {
203	            throw new IllegalArgumentException("Invalid value for [es.total_memory_bytes]: [" + memoryOverrideProperty + "]", e);
204	        }
205	    }
