249	    /**
250	     * The system load averages as an array.
251	     *
252	     * On Windows, this method returns {@code null}.
253	     *
254	     * On Linux, this method returns the 1, 5, and 15-minute load averages.
255	     *
256	     * On macOS, this method should return the 1-minute load average.
257	     *
258	     * @return the available system load averages or {@code null}
259	     */
260	    final double[] getSystemLoadAverage() {
261	        if (Constants.WINDOWS) {
262	            return null;
263	        } else if (Constants.LINUX) {
264	            try {
265	                final String procLoadAvg = readProcLoadavg();
266	                assert procLoadAvg.matches("(\\d+\\.\\d+\\s+){3}\\d+/\\d+\\s+\\d+");
267	                final String[] fields = procLoadAvg.split("\\s+");
268	                return new double[] { Double.parseDouble(fields[0]), Double.parseDouble(fields[1]), Double.parseDouble(fields[2]) };
269	            } catch (final IOException e) {
270	                if (logger.isDebugEnabled()) {
271	                    logger.debug("error reading /proc/loadavg", e);
272	                }
273	                return null;
274	            }
275	        } else {
276	            assert Constants.MAC_OS_X;
277	            if (getSystemLoadAverage == null) {
278	                return null;
279	            }
280	            try {
281	                final double oneMinuteLoadAverage = (double) getSystemLoadAverage.invoke(osMxBean);
282	                return new double[] { oneMinuteLoadAverage >= 0 ? oneMinuteLoadAverage : -1, -1, -1 };
283	            } catch (IllegalAccessException | InvocationTargetException e) {
284	                if (logger.isDebugEnabled()) {
285	                    logger.debug("error reading one minute load average from operating system", e);
286	                }
287	                return null;
288	            }
289	        }
290	    }
