292	    /**
293	     * The line from {@code /proc/loadavg}. The first three fields are the load averages averaged over 1, 5, and 15 minutes. The fourth
294	     * field is two numbers separated by a slash, the first is the number of currently runnable scheduling entities, the second is the
295	     * number of scheduling entities on the system. The fifth field is the PID of the most recently created process.
296	     *
297	     * @return the line from {@code /proc/loadavg} or {@code null}
298	     */
299	    @SuppressForbidden(reason = "access /proc/loadavg")
300	    String readProcLoadavg() throws IOException {
301	        return readSingleLine(PathUtils.get("/proc/loadavg"));
302	    }
