308	    /**
309	     * Returns the system CPU usage as a value in range [0.0, 1.0]. May return a negative value if the CPU load information is not
310	     * available.
311	     */
312	    public static double getCpuLoad() {
313	        return Probes.getLoad(getCpuLoad, osMxBean);
314	    }
