316	    public static int getAvailableProcessors() {
317	        if (getAvailableProcessors == null) {
318	            logger.warn("getAvailableProcessors is not available");
319	            return 0;
320	        }
321	        try {
322	            int availableProcessors = (int) getAvailableProcessors.invoke(osMxBean);
323	            if (availableProcessors <= 0) {
324	                logger.debug("OS reported a non-positive number of available processors [{}]", availableProcessors);
325	                return 0;
326	            }
327	            return availableProcessors;
328	        } catch (Exception e) {
329	            logger.warn("exception retrieving available processors", e);
330	            return 0;
331	        }
332	    }
