334	    /**
335	     * Reads a file containing a single line.
336	     *
337	     * @param path path to the file to read
338	     * @return the single line
339	     * @throws IOException if an I/O exception occurs reading the file
340	     * @throws IllegalStateException if the file contains zero lines
341	     */
342	    static String readSingleLine(final Path path) throws IOException {
343	        final List<String> lines = Files.readAllLines(path);
344	        if (lines.isEmpty()) {
345	            throw new IllegalStateException(Strings.format("File %s is empty, exactly one line was expected", path));
346	        }
347	        assert lines.size() == 1 : String.join("\n", lines);
348	        return lines.getFirst();
349	    }
350	
351	    @Nullable
352	    private static String maybeSingleLine(final List<String> lines) {
353	        return lines.size() == 1 ? lines.getFirst() : null;
354	    }
355	
356	    // this property is to support a hack to workaround an issue with Docker containers mounting the cgroups hierarchy inconsistently with
357	    // respect to /proc/self/cgroup; for Docker containers this should be set to "/"
358	    private static final String CONTROL_GROUPS_HIERARCHY_OVERRIDE = System.getProperty("es.cgroups.hierarchy.override");
359	
360	    /**
361	     * A map of the control groups to which the Elasticsearch process belongs. Note that this is a map because the control groups can vary
362	     * from subsystem to subsystem. Additionally, this map can not be cached because a running process can be reclassified.
363	     *
364	     * @return a map from subsystems to the control group for the Elasticsearch process.
365	     * @throws IOException if an I/O exception occurs reading {@code /proc/self/cgroup}
366	     */
367	    private Map<String, String> getControlGroups() throws IOException {
368	        final List<String> lines = readProcSelfCgroup();
369	        final Map<String, String> controllerMap = new HashMap<>();
370	        for (final String line : lines) {
371	            /*
372	             * The virtual file /proc/self/cgroup lists the control groups that the Elasticsearch process is a member of. Each line contains
373	             * three colon-separated fields of the form hierarchy-ID:subsystem-list:cgroup-path. For cgroups version 1 hierarchies, the
374	             * subsystem-list is a comma-separated list of subsystems. The subsystem-list can be empty if the hierarchy represents a cgroups
375	             * version 2 hierarchy. The cgroup-path field is a path and may contain additional colons.
376	             */
377	            final String[] fields = line.split(":", 3);
378	            assert fields.length == 3;
379	            final String[] controllers = fields[1].split(",");
380	            for (final String controller : controllers) {
381	                final String controlGroupPath;
382	                if (CONTROL_GROUPS_HIERARCHY_OVERRIDE != null) {
383	                    /*
384	                     * Docker violates the relationship between /proc/self/cgroup and the /sys/fs/cgroup hierarchy. It's possible that this
385	                     * will be fixed in future versions of Docker with cgroup namespaces, but this requires modern kernels. Thus, we provide
386	                     * an undocumented hack for overriding the control group path. Do not rely on this hack, it will be removed.
387	                     */
388	                    controlGroupPath = CONTROL_GROUPS_HIERARCHY_OVERRIDE;
389	                } else {
390	                    controlGroupPath = fields[2];
391	                }
392	                final String previous = controllerMap.put(controller, controlGroupPath);
393	                assert previous == null;
394	            }
395	        }
396	        return controllerMap;
397	    }
