399	    /**
400	     * The lines from {@code /proc/self/cgroup}. This file represents the control groups to which the Elasticsearch process belongs. Each
401	     * line in this file represents a control group hierarchy of the form
402	     * <p>
403	     * {@code (\d+):((?:[^:,]+(?:,[^:,]+)*)?):(/.*)}
404	     * <p>
405	     * with the first field representing the hierarchy ID, the second field representing a comma-separated list of the subsystems bound to
406	     * the hierarchy, and the last field representing the control group. The control group is a path and may contain additional colons.
407	     *
408	     * @return the lines from {@code /proc/self/cgroup}
409	     * @throws IOException if an I/O exception occurs reading {@code /proc/self/cgroup}
410	     */
411	    @SuppressForbidden(reason = "access /proc/self/cgroup")
412	    List<String> readProcSelfCgroup() throws IOException {
413	        final List<String> lines = Files.readAllLines(PathUtils.get("/proc/self/cgroup"));
414	        assert lines != null && lines.isEmpty() == false;
415	        return lines;
416	    }
