419	     * The total CPU time in nanoseconds consumed by all tasks in the cgroup to which the Elasticsearch process belongs for the {@code
420	     * cpuacct} subsystem.
421	     *
422	     * @param controlGroup the control group for the Elasticsearch process for the {@code cpuacct} subsystem
423	     * @return the total CPU time in nanoseconds
424	     * @throws IOException if an I/O exception occurs reading {@code cpuacct.usage} for the control group
425	     */
426	    private BigInteger getCgroupCpuAcctUsageNanos(final String controlGroup) throws IOException {
427	        return new BigInteger(readSysFsCgroupCpuAcctCpuAcctUsage(controlGroup));
428	    }
