443	    @Nullable
444	    private long[] getCgroupV2CpuLimit(String controlGroup) throws IOException {
445	        final var entry = maybeSingleLine(readCgroupV2CpuLimit(controlGroup));
446	        if (entry == null) {
447	            return null;
448	        }
449	        String[] parts = entry.split("\\s+");
450	        if (parts.length != 2) {
451	            return null;
452	        }
453	
454	        long[] values = new long[2];
455	        values[0] = "max".equals(parts[0]) ? -1L : Long.parseLong(parts[0]);
456	        values[1] = Long.parseLong(parts[1]);
457	        return values;
458	    }
