507	     *
508	     * @param controlGroup the control group to which the Elasticsearch process belongs for the {@code cpu} subsystem
509	     * @return the line from {@code cpu.cfs_quota_us}
510	     * @throws IOException if an I/O exception occurs reading {@code cpu.cfs_quota_us} for the control group
511	     */
512	    @SuppressForbidden(reason = "access /sys/fs/cgroup/cpu")
513	    String readSysFsCgroupCpuAcctCpuAcctCfsQuota(final String controlGroup) throws IOException {
514	        return readSingleLine(PathUtils.get("/sys/fs/cgroup/cpu", controlGroup, "cpu.cfs_quota_us"));
