517	    /**
518	     * The CPU time statistics for all tasks in the Elasticsearch control group.
519	     *
520	     * @param controlGroup the control group for the Elasticsearch process for the {@code cpuacct} subsystem
521	     * @return the CPU time statistics
522	     * @throws IOException if an I/O exception occurs reading {@code cpu.stat} for the control group
523	     */
524	    private OsStats.Cgroup.CpuStat getCgroupCpuAcctCpuStat(final String controlGroup) throws IOException {
525	        final var SENTINEL_VALUE = BigInteger.valueOf(-1);
526	        final List<String> lines = readSysFsCgroupCpuAcctCpuStat(controlGroup);
527	        var numberOfPeriods = SENTINEL_VALUE;
528	        var numberOfTimesThrottled = SENTINEL_VALUE;
529	        var timeThrottledNanos = SENTINEL_VALUE;
530	        for (final String line : lines) {
531	            final String[] fields = line.split("\\s+");
532	            switch (fields[0]) {
533	                case "nr_periods" -> numberOfPeriods = new BigInteger(fields[1]);
534	                case "nr_throttled" -> numberOfTimesThrottled = new BigInteger(fields[1]);
535	                case "throttled_time" -> timeThrottledNanos = new BigInteger(fields[1]);
536	            }
537	        }
538	        assert numberOfPeriods.equals(SENTINEL_VALUE) == false;
539	        assert numberOfTimesThrottled.equals(SENTINEL_VALUE) == false;
540	        assert timeThrottledNanos.equals(SENTINEL_VALUE) == false;
541	        return new OsStats.Cgroup.CpuStat(numberOfPeriods, numberOfTimesThrottled, timeThrottledNanos);
542	    }
