544	    /**
545	     * Returns the lines from {@code cpu.stat} for the control group to which the Elasticsearch process belongs for the {@code cpu}
546	     * subsystem. These lines represent the CPU time statistics and have the form
547	     * <blockquote><pre>
548	     * nr_periods \d+
549	     * nr_throttled \d+
550	     * throttled_time \d+
551	     * </pre></blockquote>
552	     * where {@code nr_periods} is the number of period intervals as specified by {@code cpu.cfs_period_us} that have elapsed, {@code
553	     * nr_throttled} is the number of times tasks in the given control group have been throttled, and {@code throttled_time} is the total
554	     * time in nanoseconds for which tasks in the given control group have been throttled.
555	     *
556	     * If the burst feature of the scheduler is enabled, the statistics contain an additional two fields of the form
557	     * <blockquote><pre>
558	     * nr_bursts \d+
559	     * burst_time
560	     * </pre></blockquote>
561	     *
562	     * When schedstat_enabled is enabled, an additional statistics information {@code wait_sum} will also be available
563	     * <blockquote><pre>
564	     * wait_sum \d+
565	     * </pre></blockquote>
566	     * {@code wait_sum} represent the conflict between task groups, which is simply sum the wait time of group's cfs_rq
567	     *  These three additional fields are currently ignored.
568	     * @param controlGroup the control group to which the Elasticsearch process belongs for the {@code cpu} subsystem
569	     * @return the lines from {@code cpu.stat}
570	     * @throws IOException if an I/O exception occurs reading {@code cpu.stat} for the control group
571	     */
572	    @SuppressForbidden(reason = "access /sys/fs/cgroup/cpu")
573	    List<String> readSysFsCgroupCpuAcctCpuStat(final String controlGroup) throws IOException {
574	        final List<String> lines = Files.readAllLines(PathUtils.get("/sys/fs/cgroup/cpu", controlGroup, "cpu.stat"));
575	        assert lines != null && (lines.size() >= 3);
576	        return lines;
577	    }
