695	    /**
696	     * Checks if cgroup stats are available by checking for the existence of {@code /proc/self/cgroup}, {@code /sys/fs/cgroup/cpu},
697	     * {@code /sys/fs/cgroup/cpuacct} and {@code /sys/fs/cgroup/memory}.
698	     *
699	     * @return {@code true} if the stats are available, otherwise {@code false}
700	     */
701	    @SuppressForbidden(reason = "access /proc/self/cgroup, /sys/fs/cgroup/cpu, /sys/fs/cgroup/cpuacct and /sys/fs/cgroup/memory")
702	    boolean areCgroupStatsAvailable() throws IOException {
703	        if (Files.exists(PathUtils.get("/proc/self/cgroup")) == false) {
704	            return false;
705	        }
706	
707	        List<String> lines = readProcSelfCgroup();
708	
709	        // cgroup v2
710	        if (lines.size() == 1 && lines.get(0).startsWith("0::")) {
711	            return Stream.of("/sys/fs/cgroup/cpu.stat", "/sys/fs/cgroup/memory.stat").allMatch(path -> Files.exists(PathUtils.get(path)));
712	        }
713	
714	        return Stream.of("/sys/fs/cgroup/cpu", "/sys/fs/cgroup/cpuacct", "/sys/fs/cgroup/memory")
715	            .allMatch(path -> Files.exists(PathUtils.get(path)));
716	    }
