718	    /**
719	     * The CPU statistics for all tasks in the Elasticsearch control group.
720	     *
721	     * @param controlGroup the control group to which the Elasticsearch process belongs for the {@code memory} subsystem
722	     * @return the CPU statistics
723	     * @throws IOException if an I/O exception occurs reading {@code cpu.stat} for the control group
724	     */
725	    @SuppressForbidden(reason = "Uses PathUtils.get to generate meaningful assertion messages")
726	    private Map<String, BigInteger> getCgroupV2CpuStats(String controlGroup) throws IOException {
727	        final List<String> lines = readCgroupV2CpuStats(controlGroup);
728	        final Map<String, BigInteger> stats = new HashMap<>();
729	        final BigInteger SENTINEL_VALUE = BigInteger.valueOf(-1);
730	
731	        for (String line : lines) {
732	            String[] parts = line.split("\\s+");
733	            assert parts.length == 2 : "Corrupt cpu.stat line: [" + line + "]";
734	            stats.put(parts[0], new BigInteger(parts[1]));
735	        }
736	
737	        final List<String> expectedKeys = List.of("system_usec", "usage_usec", "user_usec");
738	        expectedKeys.forEach(key -> {
739	            assert stats.containsKey(key) : "[" + key + "] missing from " + PathUtils.get("/sys/fs/cgroup", controlGroup, "cpu.stat");
740	            assert stats.get(key).compareTo(SENTINEL_VALUE) != 0 : stats.get(key).toString();
741	        });
742	
743	        final List<String> optionalKeys = List.of("nr_periods", "nr_throttled", "throttled_usec");
744	        optionalKeys.forEach(key -> {
745	            if (stats.containsKey(key) == false) {
746	                stats.put(key, BigInteger.ZERO);
747	            }
748	            assert stats.get(key).compareTo(SENTINEL_VALUE) != 0
749	                : "[" + key + "] in " + PathUtils.get("/sys/fs/cgroup", controlGroup, "cpu.stat") + " is -1";
750	        });
751	
752	        return stats;
753	    }
