760	    /**
761	     * Basic cgroup stats.
762	     *
763	     * @return basic cgroup stats, or {@code null} if an I/O exception occurred reading the cgroup stats
764	     */
765	    private OsStats.Cgroup getCgroup() {
766	        try {
767	            if (areCgroupStatsAvailable() == false) {
768	                return null;
769	            }
770	
771	            final Map<String, String> controllerMap = getControlGroups();
772	            assert controllerMap.isEmpty() == false;
773	
774	            final String cpuAcctControlGroup;
775	            final BigInteger cgroupCpuAcctUsageNanos;
776	            final long cgroupCpuAcctCpuCfsPeriodMicros;
777	            final long cgroupCpuAcctCpuCfsQuotaMicros;
778	            final String cpuControlGroup;
779	            final OsStats.Cgroup.CpuStat cpuStat;
780	            final String memoryControlGroup;
781	            final String cgroupMemoryLimitInBytes;
782	            final String cgroupMemoryUsageInBytes;
783	
784	            if (controllerMap.size() == 1 && controllerMap.containsKey("")) {
785	                // There's a single hierarchy for all controllers
786	                cpuControlGroup = cpuAcctControlGroup = memoryControlGroup = controllerMap.get("");
787	
788	                // `cpuacct` was merged with `cpu` in v2
789	                final Map<String, BigInteger> cpuStatsMap = getCgroupV2CpuStats(cpuControlGroup);
790	
791	                final BigInteger THOUSAND = BigInteger.valueOf(1000);
792	
793	                cgroupCpuAcctUsageNanos = cpuStatsMap.get("usage_usec").multiply(THOUSAND); // convert from micros to nanos
794	
795	                long[] cpuLimits = getCgroupV2CpuLimit(cpuControlGroup);
796	                if (cpuLimits == null) {
797	                    logger.debug("no cpu_quota and cpu_period data found in cpu.max");
798	                    return null;
799	                }
800	                cgroupCpuAcctCpuCfsQuotaMicros = cpuLimits[0];
801	                cgroupCpuAcctCpuCfsPeriodMicros = cpuLimits[1];
802	
803	                cpuStat = new OsStats.Cgroup.CpuStat(
804	                    cpuStatsMap.get("nr_periods"),
805	                    cpuStatsMap.get("nr_throttled"),
806	                    cpuStatsMap.get("throttled_usec").multiply(THOUSAND)
807	                );
808	
809	                cgroupMemoryLimitInBytes = getCgroupV2MemoryLimitInBytes(memoryControlGroup);
810	                cgroupMemoryUsageInBytes = getCgroupV2MemoryUsageInBytes(memoryControlGroup);
811	            } else {
812	                cpuAcctControlGroup = controllerMap.get("cpuacct");
813	                if (cpuAcctControlGroup == null) {
814	                    logger.debug("no [cpuacct] data found in cgroup stats");
815	                    return null;
816	                }
817	                cgroupCpuAcctUsageNanos = getCgroupCpuAcctUsageNanos(cpuAcctControlGroup);
818	
819	                cpuControlGroup = controllerMap.get("cpu");
820	                if (cpuControlGroup == null) {
821	                    logger.debug("no [cpu] data found in cgroup stats");
822	                    return null;
823	                }
824	                cgroupCpuAcctCpuCfsPeriodMicros = getCgroupCpuAcctCpuCfsPeriodMicros(cpuControlGroup);
825	                cgroupCpuAcctCpuCfsQuotaMicros = getCgroupCpuAcctCpuCfsQuotaMicros(cpuControlGroup);
826	                cpuStat = getCgroupCpuAcctCpuStat(cpuControlGroup);
827	
828	                memoryControlGroup = controllerMap.get("memory");
829	                if (memoryControlGroup == null) {
830	                    logger.debug("no [memory] data found in cgroup stats");
831	                    return null;
832	                }
833	                cgroupMemoryLimitInBytes = getCgroupMemoryLimitInBytes(memoryControlGroup);
834	                cgroupMemoryUsageInBytes = getCgroupMemoryUsageInBytes(memoryControlGroup);
835	            }
836	
837	            return new OsStats.Cgroup(
838	                cpuAcctControlGroup,
839	                cgroupCpuAcctUsageNanos,
840	                cpuControlGroup,
841	                cgroupCpuAcctCpuCfsPeriodMicros,
842	                cgroupCpuAcctCpuCfsQuotaMicros,
843	                cpuStat,
844	                memoryControlGroup,
845	                cgroupMemoryLimitInBytes,
846	                cgroupMemoryUsageInBytes
847	            );
848	        } catch (final IOException e) {
849	            logger.debug("error reading control group stats", e);
850	            return null;
851	        }
852	    }
