878	    private static OptionalLong parseCgroupBytes(String value) {
879	        if (value == null || "max".equals(value)) {
880	            return OptionalLong.empty();
881	        }
882	        try {
883	            BigInteger bigInt = new BigInteger(value);
884	            if (bigInt.signum() < 0) {
885	                return OptionalLong.empty();
886	            }
887	            return OptionalLong.of(bigInt.longValueExact());
888	        } catch (NumberFormatException | ArithmeticException e) {
889	            return OptionalLong.empty();
890	        }
891	    }
