905	    private String getPrettyName() throws IOException {
906	        // TODO: return a prettier name on non-Linux OS
907	        if (Constants.LINUX) {
908	            /*
909	             * We read the lines from /etc/os-release (or /usr/lib/os-release) to extract the PRETTY_NAME. The format of this file is
910	             * newline-separated key-value pairs. The key and value are separated by an equals symbol (=). The value can unquoted, or
911	             * wrapped in single- or double-quotes.
912	             */
913	            final List<String> etcOsReleaseLines = readOsRelease();
914	            final List<String> prettyNameLines = etcOsReleaseLines.stream().filter(line -> line.startsWith("PRETTY_NAME")).toList();
915	            assert prettyNameLines.size() <= 1 : prettyNameLines;
916	            final Optional<String> maybePrettyNameLine = prettyNameLines.size() == 1
917	                ? Optional.of(prettyNameLines.get(0))
918	                : Optional.empty();
919	            if (maybePrettyNameLine.isPresent()) {
920	                // we trim since some OS contain trailing space, for example, Oracle Linux Server 6.9 has a trailing space after the quote
921	                final String trimmedPrettyNameLine = maybePrettyNameLine.get().trim();
922	                final Matcher matcher = Pattern.compile("PRETTY_NAME=(\"?|'?)?([^\"']+)\\1").matcher(trimmedPrettyNameLine);
923	                final boolean matches = matcher.matches();
924	                assert matches : trimmedPrettyNameLine;
925	                assert matcher.groupCount() == 2 : trimmedPrettyNameLine;
926	                return matcher.group(2);
927	            } else {
928	                return Constants.OS_NAME;
929	            }
930	
931	        } else {
932	            return Constants.OS_NAME;
933	        }
934	    }
