936	    /**
937	     * The lines from {@code /etc/os-release} or {@code /usr/lib/os-release} as a fallback, with an additional fallback to
938	     * {@code /etc/system-release}. These files represent identification of the underlying operating system. The structure of the file is
939	     * newlines of key-value pairs of shell-compatible variable assignments.
940	     *
941	     * @return the lines from {@code /etc/os-release} or {@code /usr/lib/os-release} or {@code /etc/system-release}
942	     * @throws IOException if an I/O exception occurs reading {@code /etc/os-release} or {@code /usr/lib/os-release} or
943	     *                     {@code /etc/system-release}
944	     */
945	    @SuppressForbidden(reason = "access /etc/os-release or /usr/lib/os-release or /etc/system-release")
946	    List<String> readOsRelease() throws IOException {
947	        final List<String> lines;
948	        if (Files.exists(PathUtils.get("/etc/os-release"))) {
949	            lines = Files.readAllLines(PathUtils.get("/etc/os-release"));
950	            assert lines != null && lines.isEmpty() == false;
951	            return lines;
952	        } else if (Files.exists(PathUtils.get("/usr/lib/os-release"))) {
953	            lines = Files.readAllLines(PathUtils.get("/usr/lib/os-release"));
954	            assert lines != null && lines.isEmpty() == false;
955	            return lines;
956	        } else if (Files.exists(PathUtils.get("/etc/system-release"))) {
957	            // fallback for older Red Hat-like OS
958	            lines = Files.readAllLines(PathUtils.get("/etc/system-release"));
959	            assert lines != null && lines.size() == 1;
960	            return Collections.singletonList("PRETTY_NAME=\"" + lines.get(0) + "\"");
961	        } else {
962	            return Collections.emptyList();
963	        }
964	    }
